"""Original, reviewed German/Turkish story source. Stable scene/choice IDs."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
stories=[]
def story(slug,title,de,level,category,description,art):
    s=dict(id='story-'+slug,title=title,germanTitle=de,level=level,category=category,description=description,art=art,minutes=3 if level=='A1' else 4,start='start',scenes=[])
    stories.append(s); return s
def node(s,id,title,art,lines,words,q,choices=(),ending=None):
    n=dict(id=id,title=title,art=art,lines=[dict(de=l[0],tr=l[1],**({'speaker':l[2]} if len(l)>2 else {})) for l in lines],words=words,choices=[dict(id=id+'-'+str(i+1),de=c[0],tr=c[1],to=c[2]) for i,c in enumerate(choices)],question=dict(prompt=q[0],options=q[1],correct=q[1][0],explanation=q[2]))
    if ending:n['ending']=ending
    s['scenes'].append(n)

s=story('cafe','Kafede Bir Gün','Ein Tag im Café','A1','daily','Küçük bir kafede bir fincan çay, yeni bir arkadaş ya da sessiz bir kitap seni bekliyor.','cafe')
