node(s,'friends','İki kişi, bir dil','cafe',[('Du und Ben lernt fünf neue Wörter. Der Tee ist gut.','Ben ile beş yeni kelime öğreniyorsunuz. Çay güzel.'),('Morgen komme ich wieder!','Yarın yine geleceğim!','Ben')],['Tee','gut'],('Birlikte kaç yeni kelime öğreniyorsunuz?',['Beş','On','İki'],'Anlatıda “fünf neue Wörter” deniyor.'),ending='Yeni öğrenme arkadaşın')
node(s,'book','Sessiz bir sayfa','cafe',[('Du liest dein Buch am Fenster. Ben lächelt und liest auch.','Pencerede kitabını okuyorsun. Ben gülümsüyor ve o da okuyor.'),('Dein Tee ist noch warm. Du bist sehr zufrieden.','Çayın hâlâ sıcak. Çok memnunsun.')],['Buch','warm'],('Bu sonda ne yapıyorsun?',['Kitap okuyorsun','Şarkı söylüyorsun','Alışveriş yapıyorsun'],'Kitabını pencere kenarında okuyorsun.'),ending='Kitapla küçük bir mola')
node(s,'music','Bahçenin melodisi','garden',[('Im Garten spielt eine Frau Gitarre. Du hörst zu.','Bahçede bir kadın gitar çalıyor. Dinliyorsun.'),('Mia bringt deinen Kaffee. Ihr hört zusammen Musik.','Mia kahveni getiriyor. Birlikte müzik dinliyorsunuz.')],['Garten','Frau','Musik'],('Bahçede hangi çalgı çalınıyor?',['Gitar','Keman','Davul'],'Kadın gitar çalıyor: “spielt Gitarre”.'),ending='Kahveli bahçe konseri')
