s=story('geschenk','Kayıp Hediye','Das verlorene Geschenk','A1','mystery','Lea’nın doğum günü hediyesi kayıp! Çantana mı bakacaksın, fırına mı döneceksin?','gift')
node(s,'start','Bir paket eksik','gift',[('Heute hat Lea Geburtstag. Du hast ein Geschenk für sie.','Bugün Lea’nın doğum günü. Onun için bir hediyen var.'),('Aber wo ist das Geschenk? Deine Tasche ist offen.','Ama hediye nerede? Çantan açık.')],['Geschenk','Tasche'],('Hediye kimin için?',['Lea için','Ben için','Mia için'],'Bugün Lea’nın doğum günü.'),[('Ich suche in meiner Tasche.','Çantamda arıyorum.','bag'),('Ich gehe zurück zur Bäckerei.','Fırına geri dönüyorum.','bakery')])
node(s,'bag','Çantadaki küçük not','gift',[('In der Tasche liegt ein Zettel. Darauf steht: Anna hat dein Geschenk.','Çantada bir not var. Üstünde şöyle yazıyor: Hediyen Anna’da.'),('Anna wohnt neben dir. Aber ihre Tür ist zu.','Anna senin yanında oturuyor. Ama kapısı kapalı.')],['Tasche','Tür'],('Notta hediye kimde görünüyor?',['Anna’da','Lea’da','Fırıncıda'],'Notta “Anna hat dein Geschenk” yazıyor.'),[('Ich rufe Anna an.','Anna’yı arıyorum.','call'),('Ich warte vor der Tür.','Kapının önünde bekliyorum.','wait')])
node(s,'bakery','Fırıncının ipucu','cafe',[('Der Bäcker zeigt auf eine Bank. Dort liegt ein rotes Paket.','Fırıncı bir bankı gösteriyor. Orada kırmızı bir paket duruyor.'),('Neben der Bank sitzt ein Junge. Er hält auch ein Paket.','Bankın yanında bir çocuk oturuyor. O da bir paket tutuyor.')],['rot','Junge'],('Bankta ne var?',['Kırmızı bir paket','Mavi bir kitap','Yeşil bir çanta'],'Bankta kırmızı bir paket duruyor.'),[('Ich schaue auf den Namen am Paket.','Paketteki isme bakıyorum.','name'),('Ich frage den Jungen.','Çocuğa soruyorum.','boy')])
node(s,'call','Bir telefonla gelen gülümseme','gift',[('Anna antwortet: Dein Geschenk ist bei Lea!','Anna cevap veriyor: Hediyen Lea’da!'),('Du gehst zu Lea. Sie öffnet das Geschenk und lacht.','Lea’ya gidiyorsun. Hediyeyi açıyor ve gülüyor.')],['Geschenk'],('Hediye aslında nerede?',['Lea’da','Çantanda','Bankta'],'Anna hediyeyi zaten Lea’ya götürmüş.'),ending='Sürpriz senden önce geldi')
node(s,'wait','Komşunun sürprizi','gift',[('Anna kommt nach Hause. Sie hat dein Geschenk und einen Kuchen.','Anna eve geliyor. Yanında hediyen ve bir pasta var.'),('Ihr geht zusammen zu Lea. Jetzt beginnt die Feier.','Birlikte Lea’ya gidiyorsunuz. Şimdi kutlama başlıyor.')],['Kuchen','Haus'],('Anna hediyenin yanında ne getiriyor?',['Pasta','Çay','Kitap'],'Anna bir pasta da getiriyor.'),ending='Birlikte kutlamaya')
node(s,'name','Etiketteki isim','gift',[('Auf dem roten Paket steht Lea. Es ist dein Geschenk!','Kırmızı paketin üstünde Lea yazıyor. Bu senin hediyen!'),('Du nimmst es mit. Lea freut sich über das Buch.','Yanına alıyorsun. Lea kitaba seviniyor.')],['rot','Buch'],('Hediyenin içinde ne var?',['Kitap','Gitar','Çiçek'],'Lea kitaba seviniyor.'),ending='İsim doğru, hediye tamam')
node(s,'boy','İki paket, iki yol','gift',[('Der Junge sagt: Das rote Paket ist für Lea. Mein Paket ist für meinen Bruder.','Çocuk diyor ki: Kırmızı paket Lea için. Benim paketim erkek kardeşim için.'),('Du bedankst dich und bringst Lea ihr Geschenk.','Teşekkür edip Lea’ya hediyesini götürüyorsun.')],['Bruder','Geschenk'],('Çocuğun kendi paketi kimin için?',['Erkek kardeşi için','Lea için','Anna için'],'Çocuk “für meinen Bruder” diyor.'),ending='Bir yabancının yardımı')

s=story('freund','Yeni Bir Arkadaş','Ein neuer Freund','A1','friendship','Parkta yalnız oturan biri var. Bir top ve bir çizim defteri iki ayrı arkadaşlığın kapısını açıyor.','park')
node(s,'start','Parkta karşılaşma','park',[('Du bist im Park. Ein Junge sitzt allein auf einer Bank.','Parktasın. Bir çocuk bankta yalnız oturuyor.'),('Neben ihm liegen ein Ball und ein Heft.','Yanında bir top ve bir defter duruyor.')],['Junge','Heft'],('Çocuğun yanında neler var?',['Top ve defter','Kedi ve çanta','Kahve ve pasta'],'Yanında bir top ve bir defter var.'),[('Hallo! Spielen wir zusammen?','Merhaba! Birlikte oynayalım mı?','play'),('Hallo! Was malst du?','Merhaba! Ne çiziyorsun?','art')])
node(s,'play','Topun peşinde','park',[('Der Junge heißt Tom. Ihr spielt mit dem Ball.','Çocuğun adı Tom. Topla oynuyorsunuz.'),('Der Ball rollt hinter einen Baum. Dort steht ein Mädchen.','Top bir ağacın arkasına yuvarlanıyor. Orada bir kız duruyor.')],['Mädchen','Baum'],('Top nereye gidiyor?',['Ağacın arkasına','Eve','Kafeye'],'Top ağacın arkasına yuvarlanıyor.'),[('Spielst du auch mit?','Sen de oynar mısın?','team'),('Danke für den Ball! Tom und ich gehen weiter.','Top için teşekkürler! Tom ile yolumuza devam ediyoruz.','walk')])
node(s,'art','Defterdeki dünya','park',[('Tom malt einen Hund. Er hat viele bunte Stifte.','Tom bir köpek çiziyor. Bir sürü renkli kalemi var.'),('Du kannst auch malen. Was möchtest du malen?','Sen de çizebilirsin. Ne çizmek istersin?','Tom')],['Hund','Stift'],('Tom ne çiziyor?',['Köpek','Balık','Ev'],'Tom bir köpek çiziyor.'),[('Ich male eine Blume.','Bir çiçek çiziyorum.','flower'),('Ich male deinen Hund.','Senin köpeğini çiziyorum.','dog')])
node(s,'team','Üç kişilik takım','park',[('Das Mädchen heißt Ela. Jetzt spielt ihr zu dritt.','Kızın adı Ela. Şimdi üç kişi oynuyorsunuz.'),('Am Abend sagt Tom: Morgen spielen wir wieder!','Akşam Tom diyor ki: Yarın yine oynayalım!')],['Abend'],('Artık kaç kişi oynuyorsunuz?',['Üç','İki','Dört'],'“zu dritt” üç kişi demektir.'),ending='Yeni takımın hazır')
node(s,'walk','Parkın ötesinde','park',[('Du und Tom geht zum See. Ihr seht einen Fisch im Wasser.','Tom ile göle gidiyorsunuz. Suda bir balık görüyorsunuz.'),('Ihr erzählt von eurer Schule. Ihr seid in derselben Klasse!','Okulunuzdan konuşuyorsunuz. Aynı sınıftasınız!')],['Fisch','Wasser','Schule'],('Tom ile hangi ortak özelliği buluyorsunuz?',['Aynı sınıftasınız','Aynı evdesiniz','Kardeşsiniz'],'Son cümlede aynı sınıfta olduğunuz ortaya çıkıyor.'),ending='Sınıftan bir dost')
node(s,'flower','İki sayfalık bahçe','garden',[('Deine Blume ist gelb. Tom malt eine rote Blume daneben.','Çiçeğin sarı. Tom yanına kırmızı bir çiçek çiziyor.'),('Ihr malt einen ganzen Garten. Das Bild ist für eure Schule.','Kocaman bir bahçe çiziyorsunuz. Resim okulunuz için.')],['Blume','gelb','rot'],('Ortak resminiz kimin için?',['Okulunuz için','Bir kafe için','Bir otel için'],'Bahçe resmi okulunuz için hazırlanıyor.'),ending='Kâğıttan ortak bahçeniz')
node(s,'dog','Gerçek model','park',[('Tom zeigt dir ein Foto. Sein Hund heißt Max.','Tom sana bir fotoğraf gösteriyor. Köpeğinin adı Max.'),('Du malst Max. Tom hängt das Bild später zu Hause auf.','Max’ı çiziyorsun. Tom daha sonra resmi evine asıyor.')],['Hund','Haus'],('Tom’un köpeğinin adı ne?',['Max','Ben','Leo'],'Tom’un köpeğinin adı Max.'),ending='Max’ın küçük portresi')

s=story('garten','Bahçedeki Sır','Das Geheimnis im Garten','A1','fantasy','Çiçeklerin arasında parlayan bir anahtar ve küçük bir ses… Bahçenin sırrını hangi yoldan çözeceksin?','garden')
node(s,'start','Yaprakların arasındaki ışık','garden',[('Du gehst in den Garten. Unter einer Blume liegt ein kleiner Schlüssel.','Bahçeye gidiyorsun. Bir çiçeğin altında küçük bir anahtar var.'),('Aus dem Baum kommt eine leise Stimme: Hallo!','Ağaçtan hafif bir ses geliyor: Merhaba!')],['Garten','Blume','Baum'],('Anahtar nerede?',['Çiçeğin altında','Evin içinde','Bankta'],'Anahtar bir çiçeğin altında.'),[('Ich nehme den Schlüssel.','Anahtarı alıyorum.','key'),('Ich höre der Stimme zu.','Sesi dinliyorum.','voice')])
node(s,'key','İki küçük kapı','garden',[('Hinter dem Baum stehen zwei kleine Häuser. Ein Haus ist blau, das andere grün.','Ağacın arkasında iki küçük ev var. Biri mavi, diğeri yeşil.'),('Der Schlüssel passt in beide Türen. Du wählst eine Tür.','Anahtar iki kapıya da uyuyor. Bir kapı seçiyorsun.')],['Haus','blau','grün','Tür'],('Kaç küçük ev var?',['İki','Bir','Üç'],'Ağacın arkasında iki ev duruyor.'),[('Ich öffne die blaue Tür.','Mavi kapıyı açıyorum.','blue'),('Ich öffne die grüne Tür.','Yeşil kapıyı açıyorum.','green')])
node(s,'voice','Lumi’nin isteği','garden',[('Eine kleine Blume spricht mit dir. Sie heißt Lumi.','Küçük bir çiçek seninle konuşuyor. Adı Lumi.'),('Ich habe Durst. Oder singst du ein Lied für mich?','Susadım. Ya da benim için bir şarkı söyler misin?','Lumi')],['Blume','Wasser'],('Seninle kim konuşuyor?',['Lumi adlı bir çiçek','Bir kedi','Bir öğretmen'],'Konuşan çiçeğin adı Lumi.'),[('Ich bringe dir Wasser.','Sana su getiriyorum.','water'),('Ich singe ein Lied für dich.','Senin için bir şarkı söylüyorum.','song')])
node(s,'blue','Yıldız odası','night',[('Im blauen Haus leuchten kleine Sterne. Du setzt dich auf einen weichen Stuhl.','Mavi evde küçük yıldızlar parlıyor. Yumuşak bir sandalyeye oturuyorsun.'),('Ein Stern fliegt auf deine Hand. Er zeigt dir den Weg nach Hause.','Bir yıldız eline uçuyor. Sana eve giden yolu gösteriyor.')],['blau','Stuhl','Hand'],('Yıldız sana ne gösteriyor?',['Eve giden yolu','Bir kitabı','Bir oyunu'],'Yıldız eve giden yolu gösteriyor.'),ending='Avucundaki yıldız')
node(s,'green','Tohum odası','garden',[('Im grünen Haus liegen viele Samen. Du pflanzt einen Samen in die Erde.','Yeşil evde çok sayıda tohum var. Toprağa bir tohum ekiyorsun.'),('Sofort wächst eine gelbe Blume. Sie sagt: Willkommen!','Hemen sarı bir çiçek büyüyor. Şöyle diyor: Hoş geldin!')],['grün','gelb','Blume'],('Ektiğin tohumdan ne çıkıyor?',['Sarı bir çiçek','Mavi bir ağaç','Bir elma'],'Tohumdan sarı bir çiçek büyüyor.'),ending='Konuşan filiz')
node(s,'water','Bir yudumla gelen renk','garden',[('Du gibst Lumi Wasser. Ihre Blätter werden wieder grün.','Lumi’ye su veriyorsun. Yaprakları yeniden yeşil oluyor.'),('Alle Blumen im Garten öffnen sich. Lumi dankt dir.','Bahçedeki bütün çiçekler açılıyor. Lumi sana teşekkür ediyor.')],['Wasser','grün','Blume'],('Lumi’ye ne veriyorsun?',['Su','Çay','Kahve'],'Susayan Lumi’ye su veriyorsun.'),ending='Canlanan bahçe')
node(s,'song','Çiçeklerin korosu','garden',[('Du singst ein Lied. Lumi und die anderen Blumen singen mit.','Bir şarkı söylüyorsun. Lumi ve diğer çiçekler eşlik ediyor.'),('Ein Schmetterling tanzt über dem Garten. Du lachst.','Bahçenin üstünde bir kelebek dans ediyor. Gülüyorsun.')],['Garten','Musik'],('Şarkına kim eşlik ediyor?',['Lumi ve çiçekler','Öğretmenin','Bir fırıncı'],'Lumi ve diğer çiçekler seninle şarkı söylüyor.'),ending='Bahçenin ortak şarkısı')

s=story('zug','Tren Yolculuğundaki Sürpriz','Eine Überraschung im Zug','A2','travel','Geciken tren planını değiştiriyor. Bir yolcuya yardım etmek mi, yeni bir rota denemek mi?','train')
node(s,'start','Peronda değişen plan','train',[('Du möchtest nach Köln fahren, aber dein Zug hat dreißig Minuten Verspätung.','Köln’e gitmek istiyorsun ama trenin otuz dakika gecikiyor.'),('Neben dir sucht eine ältere Frau ihren Fahrplan. Am anderen Gleis wartet ein Regionalzug.','Yanında yaşlı bir kadın sefer çizelgesini arıyor. Diğer peronda bir bölgesel tren bekliyor.')],['Zug','Frau'],('Tren ne kadar gecikiyor?',['Otuz dakika','On dakika','Bir saat'],'Anons, otuz dakikalık gecikme olduğunu bildiriyor.'),[('Kann ich Ihnen helfen?','Size yardım edebilir miyim?','help'),('Ich frage nach dem Regionalzug.','Bölgesel treni soruyorum.','route')])
node(s,'help','Kaybolan bağlantı','train',[('Die Frau heißt Frau Berger. Sie hat ihre Brille zu Hause vergessen.','Kadının adı Bayan Berger. Gözlüğünü evde unutmuş.'),('Du liest den Fahrplan vor. Ihr Anschluss fährt von Gleis vier.','Sefer çizelgesini sesli okuyorsun. Aktarma treni dördüncü perondan kalkıyor.')],['Haus','lesen'],('Bayan Berger evde ne unutmuş?',['Gözlüğünü','Biletini','Çantasını'],'Bu yüzden sefer çizelgesini okuyamıyor.'),[('Ich begleite Sie zum Gleis.','Size perona kadar eşlik edeyim.','platform'),('Ich schreibe die Verbindung auf.','Aktarma bilgilerini yazıyorum.','note')])
node(s,'route','Daha uzun, daha güzel','train',[('Der Mitarbeiter erklärt: Mit dem Regionalzug dauert die Fahrt länger, aber Sie sehen den Rhein.','Görevli açıklıyor: Bölgesel trenle yolculuk daha uzun sürer ama Ren Nehri’ni görürsünüz.'),('Du kannst sofort einsteigen oder auf den schnellen Zug warten.','Hemen binebilir ya da hızlı treni bekleyebilirsin.')],['Zug','sehen'],('Bölgesel trenin avantajı ne?',['Ren Nehri’ni görmek','Daha hızlı olmak','Ücretsiz yemek'],'Bölgesel rota daha uzun ama nehir manzarası sunuyor.'),[('Ich nehme den Regionalzug.','Bölgesel trene biniyorum.','river'),('Ich warte auf meinen Zug.','Kendi trenimi bekliyorum.','fast')])
node(s,'platform','Bir teşekkür kartı','train',[('Ihr erreicht Gleis vier rechtzeitig. Frau Berger schenkt dir eine Postkarte von Köln.','Dördüncü perona zamanında ulaşıyorsunuz. Bayan Berger sana Köln’den bir kartpostal veriyor.'),('Später fährst du mit deinem Zug weiter. Auf der Karte steht: Vielen Dank!','Sonra kendi treninle devam ediyorsun. Kartta şöyle yazıyor: Çok teşekkürler!')],['Zug'],('Bayan Berger sana ne veriyor?',['Kartpostal','Kitap','Bilet'],'Yardımın için bir Köln kartpostalı veriyor.'),ending='Yolculuktan kalan teşekkür')
node(s,'note','Küçük bir notun gücü','train',[('Mit deinem Zettel findet Frau Berger den richtigen Zug allein. Du bleibst am Bahnsteig.','Notun sayesinde Bayan Berger doğru treni tek başına buluyor. Sen peronda kalıyorsun.'),('Du kaufst einen Tee und wartest entspannt auf deine Weiterfahrt.','Bir çay alıp yolculuğunun devamını rahatça bekliyorsun.')],['Tee','Zug'],('Bayan Berger doğru treni nasıl buluyor?',['Yazdığın notla','Telefon uygulamasıyla','Şoförle konuşarak'],'Yazdığın aktarma bilgileri ona yol gösteriyor.'),ending='Bir not, iki rahat yolcu')
node(s,'river','Penceredeki nehir','train',[('Der Regionalzug fährt langsam am Rhein entlang. Du fotografierst kleine Häuser am Wasser.','Bölgesel tren Ren boyunca yavaşça gidiyor. Suyun kenarındaki küçük evleri fotoğraflıyorsun.'),('Du kommst später an, aber die Aussicht war die längere Fahrt wert.','Daha geç varıyorsun ama manzara uzun yolculuğa değdi.')],['Wasser','Haus'],('Bu yolculukta neyi fotoğraflıyorsun?',['Su kenarındaki evleri','Bir müzeyi','Bir kafeyi'],'Trenden su kenarındaki evleri fotoğraflıyorsun.'),ending='Yavaş yolun güzel manzarası')
node(s,'fast','Tam zamanında','train',[('Nach einer halben Stunde kommt dein Zug. Du findest einen ruhigen Platz.','Yarım saat sonra trenin geliyor. Sessiz bir yer buluyorsun.'),('In Köln wartet deine Freundin am Bahnhof. Ihr habt noch Zeit für einen Spaziergang.','Köln’de arkadaşın istasyonda bekliyor. Yürüyüş için hâlâ zamanınız var.')],['Freundin','Zeit'],('Köln’de seni kim karşılıyor?',['Arkadaşın','Bayan Berger','Tren görevlisi'],'İstasyonda kız arkadaşın bekliyor.'),ending='Beklemeye değen buluşma')

s=story('nachbarn','Yeni Mahallede İlk Gün','Der erste Tag im neuen Viertel','A2','germany','Yeni bir mahallede bir not, bir davet ve küçük bir yardım seni komşularınla tanıştırıyor.','town')
node(s,'start','Apartman girişindeki not','town',[('Du bist gestern umgezogen. Im Treppenhaus hängt eine Einladung zum Nachbarschaftsfest.','Dün taşındın. Apartman merdivenlerinde mahalle şenliğine bir davet asılı.'),('Gleichzeitig hörst du, dass dein Nachbar Hilfe beim Tragen braucht.','Aynı anda komşunun bir şeyler taşımak için yardıma ihtiyacı olduğunu duyuyorsun.')],['Haus','Nachbar'],('Ne zaman taşındın?',['Dün','Geçen yıl','Bu sabah'],'“gestern” dün demektir.'),[('Ich helfe zuerst meinem Nachbarn.','Önce komşuma yardım ediyorum.','help'),('Ich gehe zum Fest im Hof.','Avludaki şenliğe gidiyorum.','party')])
node(s,'help','Ağır kutunun içindekiler','town',[('Dein Nachbar Paul trägt eine Kiste mit Büchern. Ihr stellt sie gemeinsam in seine Wohnung.','Komşun Paul kitap dolu bir kutu taşıyor. Birlikte evine koyuyorsunuz.'),('Paul fragt: Möchtest du ein Buch ausleihen oder mit mir zum Fest gehen?','Paul soruyor: Bir kitap ödünç almak mı, benimle şenliğe gitmek mi istersin?')],['Buch','Nachbar'],('Kutunun içinde ne var?',['Kitaplar','Tabaklar','Çiçekler'],'Paul kitap dolu bir kutu taşıyor.'),[('Ich leihe gern ein Buch aus.','Seve seve bir kitap ödünç alırım.','book'),('Gehen wir zusammen zum Fest!','Şenliğe birlikte gidelim!','together')])
node(s,'party','Avluda iki masa','town',[('Im Hof stehen zwei große Tische. An einem Tisch wird gekocht, am anderen werden Spiele erklärt.','Avluda iki büyük masa var. Birinde yemek yapılıyor, diğerinde oyunlar anlatılıyor.'),('Die Nachbarin Sara begrüßt dich und fragt nach deinem Namen.','Komşun Sara seni selamlıyor ve adını soruyor.')],['Tisch','Name'],('Avluda hangi iki etkinlik var?',['Yemek ve oyun','Müzik ve yüzme','Ders ve sınav'],'Masalarda yemek hazırlanıyor ve oyunlar anlatılıyor.'),[('Ich helfe beim Kochen.','Yemek yapmaya yardım ediyorum.','cook'),('Ich probiere ein Spiel aus.','Bir oyun deniyorum.','game')])
node(s,'book','Ödünç bir başlangıç','town',[('Paul gibt dir ein Buch über die Stadt. Auf der ersten Seite findest du eine Karte.','Paul sana şehir hakkında bir kitap veriyor. İlk sayfada bir harita buluyorsun.'),('Ihr verabredet euch für Samstag, um die Stadt gemeinsam zu entdecken.','Şehri birlikte keşfetmek için cumartesiye sözleşiyorsunuz.')],['Buch','Stadt'],('Cumartesi ne yapacaksınız?',['Şehri keşfedeceksiniz','Taşınacaksınız','Trene bineceksiniz'],'Kitap, birlikte bir şehir gezisinin başlangıcı oluyor.'),ending='Kitaptan doğan şehir turu')
node(s,'together','Bir tabak daha','town',[('Paul stellt dich seinen Freunden vor. Jemand holt sofort einen weiteren Teller.','Paul seni arkadaşlarıyla tanıştırıyor. Biri hemen bir tabak daha getiriyor.'),('Beim Essen erzählt ihr von euren Hobbys. Du fühlst dich schon ein bisschen zu Hause.','Yemekte hobilerinizden konuşuyorsunuz. Kendini şimdiden biraz evinde hissediyorsun.')],['Freund','Essen'],('Seni arkadaşlarıyla kim tanıştırıyor?',['Paul','Sara','Ev sahibi'],'Paul seni arkadaş grubuna dahil ediyor.'),ending='Sofrada sana da yer var')
node(s,'cook','Paylaşılan tarif','town',[('Du schneidest Gemüse, während Sara die Suppe kocht. Sie erklärt dir ihr Familienrezept.','Sara çorbayı pişirirken sen sebzeleri doğruyorsun. Aile tarifini sana anlatıyor.'),('Am Abend nimmst du das Rezept mit. Nächste Woche möchtest du für alle kochen.','Akşam tarifi yanına alıyorsun. Gelecek hafta herkes için yemek yapmak istiyorsun.')],['Gemüse','Suppe'],('Gelecek hafta ne yapmak istiyorsun?',['Herkes için yemek yapmak','Taşınmak','Kitap almak'],'Tarifi öğrenince komşularına yemek yapmak istiyorsun.'),ending='Tariften gelen dostluk')
node(s,'game','Bir sonraki oyun gecesi','town',[('Sara erklärt dir ein Kartenspiel. Am Anfang fragst du viel, dann gewinnst du eine Runde.','Sara sana bir kart oyunu anlatıyor. Başta çok soru soruyorsun, sonra bir tur kazanıyorsun.'),('Die Nachbarn laden dich zum nächsten Spieleabend ein. Jetzt kennst du schon mehrere Namen.','Komşular seni sonraki oyun gecesine davet ediyor. Artık birkaç ismi biliyorsun.')],['Name','Nachbar'],('Komşular seni neye davet ediyor?',['Sonraki oyun gecesine','Bir düğüne','Bir derse'],'Bir sonraki oyun gecesine davet ediliyorsun.'),ending='Masadaki yeni oyuncu')

out=ROOT/'src/data/stories';out.mkdir(parents=True,exist_ok=True)
(out/'stories.json').write_text(json.dumps(stories,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(stories),'hikâye,',sum(len(s['scenes']) for s in stories),'sahne')
